CREATE TABLE "user_cards" ("card_id" TEXT NOT NULL, "lang" TEXT NOT NULL, "local_only" INTEGER NOT NULL DEFAULT 0 CHECK ("local_only" IN (0, 1)), "box" INTEGER NOT NULL CHECK(box BETWEEN 0 AND 5), "due_at" TEXT NULL, "created_at" TEXT NOT NULL, "origin" TEXT NOT NULL CHECK(origin IN ('deck', 'story')), "disabled" INTEGER NOT NULL DEFAULT 0 CHECK ("disabled" IN (0, 1)), "retired" INTEGER NOT NULL DEFAULT 0 CHECK ("retired" IN (0, 1)), "updated_at" TEXT NOT NULL, PRIMARY KEY ("card_id"));
CREATE TABLE "review_log" ("id" TEXT NOT NULL, "card_id" TEXT NOT NULL, "created_at" TEXT NOT NULL, "mode" TEXT NOT NULL CHECK(mode IN ('mixed', 'deck', 'revue', 'early')), "sentence_id" TEXT NOT NULL, "first_attempt_correct" INTEGER NOT NULL CHECK ("first_attempt_correct" IN (0, 1)), "error_count" INTEGER NOT NULL CHECK(error_count >= 0), "revealed" INTEGER NOT NULL CHECK ("revealed" IN (0, 1)), "hint_used" INTEGER NOT NULL DEFAULT 0 CHECK ("hint_used" IN (0, 1)), "box_before" INTEGER NOT NULL CHECK(box_before BETWEEN 0 AND 5), "box_after" INTEGER NOT NULL CHECK(box_after BETWEEN 1 AND 5), "due_at_after" TEXT NOT NULL, "response_ms" INTEGER NULL, "app_version" TEXT NOT NULL, "device_id" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "deck_settings" ("deck_id" TEXT NOT NULL, "active" INTEGER NOT NULL CHECK ("active" IN (0, 1)), "updated_at" TEXT NOT NULL, PRIMARY KEY ("deck_id"));
CREATE TABLE "settings" ("id" INTEGER NOT NULL CHECK(id = 1), "device_id" TEXT NOT NULL, "target_lang" TEXT NOT NULL, "updated_at" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE INDEX review_log_card ON review_log (card_id);
CREATE TRIGGER review_log_no_update BEFORE UPDATE ON review_log BEGIN SELECT RAISE(ABORT, 'review_log is append-only'); END;
CREATE TRIGGER review_log_no_delete BEFORE DELETE ON review_log BEGIN SELECT RAISE(ABORT, 'review_log is append-only'); END;
PRAGMA user_version=1;
